<?php if(ORDER_TRANSITIONS[$o['status']]): ?><form class="panel" method="post"><?=csrf()?><input type="hidden" name="action" value="status"><label>เปลี่ยนสถานะคำสั่งซื้อ<select name="status"><?php foreach(ORDER_TRANSITIONS[$o['status']] as $status): ?><option value="<?=$status?>"><?=e(t(STATUSES[$status]))?></option><?php endforeach ?></select></label><button>บันทึกสถานะ</button></form><?php endif ?>
