<?php if($o['payment_method']==='COD'&&$o['status']==='delivered'&&$o['payment_status']==='unpaid'): ?><form method="post" class="panel" data-confirm="ยืนยันว่าได้รับเงิน COD จริงแล้ว?"><?=csrf()?><button name="action" value="payment">ยืนยันได้รับเงิน COD จริงแล้ว</button></form><?php endif ?>
